mapper.select:
select doc_id, project_id, stage, title, source_type, left(original_text, 120) as original_text, chunk_count, status, create_by, create_time from ai_kb_doc where project_id = #{projectId}
and stage = #{stage}
order by create_time desc

select doc_id, project_id, stage, title, source_type, chunk_count, status, create_by, create_time from ai_kb_doc
where stage = #{stage}
order by project_id, create_time desc

select log_id, project_id, stage, query_text, chunk_ids, model_id, create_time
from ai_kb_retrieval_log


        and project_id = #{projectId}


        and stage = #{stage}


order by create_time desc, log_id desc
limit #{limit}

select doc_id, project_id, stage, title, source_type, chunk_count, status, create_by, create_time
from ai_kb_doc
where project_id = #{projectId}
  and stage <=> #{stage}
  and title = #{title}
